import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Fanout Topic Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/topic/index.md","filePath":"proposals/topic/index.md"}'),r={name:"proposals/topic/index.md"};function s(n,e,d,c,p,l){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="fanout-topic-family-proposals" tabindex="-1">Fanout Topic Family proposals <a class="header-anchor" href="#fanout-topic-family-proposals" aria-label="Permalink to &quot;Fanout Topic Family proposals&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Historical / deferred candidate family</p><p><code>topic.forms.takoform.com</code> is retained source from the earlier Provider projection. It is not part of the current official corpus (the single Edge family with 16 Forms), and this family is outside Current navigation. These pages are English-only historical/deferred proposals.</p></div><p>The Fanout Topic Family, <code>topic.forms.takoform.com</code>, is minted under <a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>: pub/sub fanout is popularly offered as a managed service by every major provider and has no de-facto standard API, so a host-neutral contract is the only portability there is. Its members fix, completely, the application-visible semantics of the proven fanout-topic shape — publish once, every subscription gets its own copy — without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: client API, data model, delivery guarantees, update and delete units, error semantics, and the capabilities exposed through typed Bindings. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>This prose accompanies the two generated Experimental candidates under <code>forms/candidates/topic.forms.takoform.com</code> and the exact <code>topic.publish</code> Interface. The generated candidate bytes are retained historical/deferred source, not the current publisher identities; these documents reserve nothing.</p><h2 id="retained-candidate-members-historical-deferred" tabindex="-1">Retained candidate members (historical/deferred) <a class="header-anchor" href="#retained-candidate-members-historical-deferred" aria-label="Permalink to &quot;Retained candidate members (historical/deferred)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./topic.html">Topic</a></td><td>identity</td><td>Fanout topic: an accepted publish is delivered, per-subscription at-least-once, to every matching subscription; nothing is retained or replayed.</td><td>A retained, replayable log or an ordered stream is a different Form.</td></tr><tr><td><a href="./topic-subscription.html">TopicSubscription</a></td><td>attachment</td><td>Subscribes one pull queue to one topic, with an optional closed attribute-equality filter policy, retry, and a dead-letter queue.</td><td>HTTPS push delivery to an author-named endpoint is a separate Form once the endpoint-authentication shape is fixed.</td></tr></tbody></table><h2 id="cross-family-composition" tabindex="-1">Cross-family composition <a class="header-anchor" href="#cross-family-composition" aria-label="Permalink to &quot;Cross-family composition&quot;">​</a></h2><p>The MVP delivery target is a <code>PullQueue</code> from <a href="./../queue/"><code>queue.forms.takoform.com</code></a>. Relations and binding instances carry an explicit <code>apiVersion</code> in their closed <code>{apiVersion, kind, name}</code> reference shape, so a cross-family target is representable without new machinery (<a href="./../../spec/binding-contract/">binding contract</a>). Designs that differ in these semantics — a retained stream, an event bus with routing rules — belong to future families per <a href="./../../spec/form-families.html">spec/form-families.md</a> and decision 0043&#39;s candidate list.</p>',10)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
